// Des: Split and canonicalize http(s) URLs for dedupe
// Flo: trim > check scheme > split host/port/path/query > drop fragment and tracking params > sort query > rebuild
// I/O: raw URL text (frontier, redirects) > Part struct or canonical URL string (caller owns)
// ===================================================================
const std = @import("std"); const mem = std.mem;
const CF = .{ .maxl = 2048, .trak = @as([]const []const u8, &.{ "utm_", "fbclid", "gclid", "msclkid", "mc_cid", "mc_eid", "igshid", "yclid", "_ga" }) };
pub const Part = struct { sche: []const u8, host: []const u8, port: u16, path: []const u8, quer: []const u8, dflt: bool };
pub fn urlSplit(raws: []const u8) !Part { const text = mem.trim(u8, raws, " \t\r\n"); if (text.len == 0 or text.len > CF.maxl) return error.BadUrl; for (text) |byte| if (byte < 0x21 or byte == 0x7f) return error.BadUrl; const sepz = mem.find(u8, text, "://") orelse return error.BadUrl; const sche = text[0..sepz]; const ishp = std.ascii.eqlIgnoreCase(sche, "http"); if (!ishp and !std.ascii.eqlIgnoreCase(sche, "https")) return error.BadUrl; var rest = text[sepz + 3 ..]; if (mem.findScalar(u8, rest, '#')) |hash| rest = rest[0..hash]; const endz = mem.findAny(u8, rest, "/?") orelse rest.len; const auth = rest[0..endz]; if (auth.len == 0 or mem.findScalar(u8, auth, '@') != null) return error.BadUrl; var host = auth; var portz: ?u16 = null; if (auth[0] == '[') { const clos = mem.findScalar(u8, auth, ']') orelse return error.BadUrl; host = auth[0 .. clos + 1]; if (clos + 1 < auth.len) { if (auth[clos + 1] != ':') return error.BadUrl; portz = std.fmt.parseInt(u16, auth[clos + 2 ..], 10) catch return error.BadUrl; } } else if (mem.findScalar(u8, auth, ':')) |colo| { host = auth[0..colo]; portz = std.fmt.parseInt(u16, auth[colo + 1 ..], 10) catch return error.BadUrl; } if (host.len == 0 or (portz != null and portz.? == 0)) return error.BadUrl; const tail = rest[endz..]; const qidx = mem.findScalar(u8, tail, '?'); const path = if (qidx) |qi| tail[0..qi] else tail; const quer = if (qidx) |qi| tail[qi + 1 ..] else ""; const dport: u16 = if (ishp) 80 else 443; return .{ .sche = if (ishp) "http" else "https", .host = host, .port = portz orelse dport, .path = if (path.len == 0) "/" else path, .quer = quer, .dflt = (portz orelse dport) == dport }; }
fn trakIs(pair: []const u8) bool { for (CF.trak) |pref| if (mem.startsWith(u8, pair, pref)) return true; return false; }
fn lessPair(_: void, left: []const u8, rite: []const u8) bool { return mem.lessThan(u8, left, rite); }
pub fn urlNorm(allo: std.mem.Allocator, raws: []const u8) ![]u8 { const part = try urlSplit(raws); var pair: std.ArrayList([]const u8) = .empty; defer pair.deinit(allo); var iter = mem.splitScalar(u8, part.quer, '&'); while (iter.next()) |item| { if (item.len == 0 or trakIs(item)) continue; try pair.append(allo, item); } mem.sort([]const u8, pair.items, {}, lessPair); const quer = try mem.join(allo, "&", pair.items); defer allo.free(quer); const hostl = try std.ascii.allocLowerString(allo, part.host); defer allo.free(hostl); const portt = if (part.dflt) try allo.dupe(u8, "") else try std.fmt.allocPrint(allo, ":{d}", .{part.port}); defer allo.free(portt); const qsep: []const u8 = if (quer.len > 0) "?" else ""; return std.fmt.allocPrint(allo, "{s}://{s}{s}{s}{s}{s}", .{ part.sche, hostl, portt, part.path, qsep, quer }); }
